/**
 * E2E suite — runs inside the VSCode extension host (SPEC.md §5).
 *
 * ESM test-runner contract (VSCode ≥ 1.90, `extHostExtensionService
 * #_doHandleExtensionTests`): the module must export
 *   run(testsPath): Promise<void>
 * — the host passes this file's own path and settles the run from the
 * returned Promise (resolves → success, rejects → failure). A second,
 * optional `onComplete(error?, failures?)` callback is passed as well;
 * this suite uses the documented Promise channel only.
 *
 * Workspace: `test/integration/workspace/` (generated by the runner) —
 * the reference mini-project (test/fixtures/*) + e2e-only cases in e2e/.
 *
 * Reference invariants (locked by the unit suite — 175 tests):
 *   5 features / 12 steps · 3 PHP / 9 definitions · 11 matching pairs
 *   · undefined step: commandes.feature line 12 (1-based)
 *   · orphan definition: CommandeSteps.php line 31 (1-based)
 *   · 0 duplicates.
 *
 * The setting-gate scenarios (orphans / enabled) run last: they mutate the
 * workspace configuration and restore it, so the reference assertions above
 * always see the default settings. The SPEC §7 restart scenario lives in
 * suite-restart.mjs (a second, fresh VSCode launch — see runner.mjs).
 */
import * as vscode from "vscode";
import assert from "node:assert/strict";
import { mkdirSync, readFileSync } from "node:fs";
import { access, chmod, rm, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";

// --- mini test framework (dependency-free, registry + run Promise) -------

const tests = [];
function test(name, fn) {
  tests.push({ name, fn });
}

// --- helpers ---------------------------------------------------------------

function workspaceRoot() {
  const roots = vscode.workspace.workspaceFolders;
  assert.ok(roots && roots.length > 0, "a workspace folder is open");
  return roots[0].uri;
}

function docUri(relPath) {
  return vscode.Uri.joinPath(workspaceRoot(), relPath);
}

/**
 * The test host starts running before `onStartupFinished` fires, so the
 * extension (activated on startup) may not be active yet — poll until it
 * is. Product activation policy stays `onStartupFinished` (the index glob
 * is user-configurable, so a lazy `workspaceContains` event could miss it).
 */
async function waitForActivation(timeoutMs = 20000) {
  const ext = vscode.extensions.getExtension("ailonn.gherkin-behat-linker");
  assert.ok(ext, "the development extension is installed");
  const start = Date.now();
  while (!ext.isActive) {
    if (Date.now() - start > timeoutMs) {
      throw new Error(`extension not activated after ${timeoutMs} ms`);
    }
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
}

/** Poll an (async) predicate until truthy — the index builds async. */
async function waitFor(label, predicate, timeoutMs = 15000) {
  const start = Date.now();
  for (;;) {
    if (await predicate()) {
      return;
    }
    if (Date.now() - start > timeoutMs) {
      throw new Error(`timeout waiting for: ${label}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
}

/** Location | Location[] | LocationLink[] → normalized {uri, range}[]. */
function toLocations(result) {
  const arr = Array.isArray(result) ? result : result ? [result] : [];
  return arr.map((l) => ({
    uri: l.targetUri ?? l.uri,
    range: l.targetRange ?? l.range,
  }));
}

/** Hover | Hover[] | undefined → concatenated plain text. */
function hoverText(hovers) {
  const arr = Array.isArray(hovers) ? hovers : hovers ? [hovers] : [];
  return arr
    .flatMap((h) => (Array.isArray(h.contents) ? h.contents : [h.contents]))
    .map((c) => (typeof c === "string" ? c : c.value ?? String(c)))
    .join("\n");
}

const ERROR = vscode.DiagnosticSeverity.Error;
const WARNING = vscode.DiagnosticSeverity.Warning;
const INFO = vscode.DiagnosticSeverity.Information;

/**
 * The squiggle spans the whole flagged line (day-1 signal): the range
 * starts at column 0 and ends at the actual line length of the source.
 */
function assertFullLineRange(root, relPath, d) {
  const line =
    readFileSync(join(root, relPath), "utf8")
      .split(/\r?\n/)[d.range.start.line] ?? "";
  // vscode.Position exposes `character` (not LSP's `column`).
  assert.equal(d.range.start.character, 0, "range starts at column 0");
  assert.equal(d.range.end.line, d.range.start.line, "range stays on the flagged line");
  assert.equal(d.range.end.character, line.length, "range ends at the line length");
}

// --- E1 smoke (harness proof, not an AC) ----------------------------------

test("E1: e2e workspace is open (reference fixtures + e2e cases)", async () => {
  const root = workspaceRoot().fsPath;
  assert.match(root, /workspace/, "the generated workspace is the folder");
  assert.equal(
    await access(join(root, "commandes.feature")).then(
      () => true,
      () => false
    ),
    true,
    "reference fixture copied"
  );
  assert.equal(
    await access(join(root, "e2e", "broken.feature")).then(
      () => true,
      () => false
    ),
    true,
    "e2e-only fixture copied"
  );
});

test("E1: extension activates and indexes the workspace (ESM main)", async () => {
  await waitForActivation();
  // Product proof, no test hook in the shipped code: activation → index
  // build → the first diagnostic published on the reference fixture.
  const doc = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  await waitFor(
    "E1: undefined-step diagnostic on the reference fixture",
    async () =>
      vscode.languages
        .getDiagnostics(doc.uri)
        .some((d) => d.severity === ERROR)
  );
  // The dev "ping" command is NOT shipped (removed in the re-challenge):
  // lock the absence — a re-introduced contributes.commands or a
  // re-registered handler would fail this suite.
  const ext = vscode.extensions.getExtension("ailonn.gherkin-behat-linker");
  assert.ok(ext, "the development extension is installed");
  assert.equal(
    ext.packageJSON.contributes?.commands,
    undefined,
    "the manifest contributes no command (the dev ping is not shipped)"
  );
  await assert.rejects(
    () => vscode.commands.executeCommand("gherkinBehat.ping"),
    // Rejection wording differs by VS Code version/path — main thread:
    // `command '<id>' not found`, extension host: `Unknown command`.
    /unknown command|not found/i,
    "executing the removed ping fails (unknown-command error)"
  );
});

// --- AC-1: feature → definition (SPEC §3) ----------------------------------

test("AC-1: feature step → PHP definition (type-agnostic, static, no vendor/)", async () => {
  await waitForActivation();
  // AC-5 (static): the workspace carries no PHP runtime at all.
  const root = workspaceRoot().fsPath;
  assert.equal(
    await access(join(root, "vendor")).then(() => true, () => false),
    false,
    "the e2e workspace has no vendor/ (AC-5)"
  );
  const doc = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  // line 6 (1-based): Quand je valide la commande "CMD-2026" avec succès
  // → @When /je valide la commande "(?P<numero>[\w.-]+)"/ — CommandeSteps.php
  //   line 15 (1-based) = line 14 (0-based).
  const pos = new vscode.Position(5, 10);
  await waitFor("AC-1: definition of the step at line 6", async () => {
    const res = await vscode.commands.executeCommand(
      "vscode.executeDefinitionProvider",
      doc.uri,
      pos
    );
    return toLocations(res).some(
      (l) => l.uri.fsPath.endsWith("CommandeSteps.php") && l.range.start.line === 14
    );
  });
});

// --- AC-2: definition → usages (reverse) -----------------------------------

test("AC-2: PHP definition → all matching feature steps (reverse)", async () => {
  await waitForActivation();
  const php = await vscode.workspace.openTextDocument(docUri("CommandeSteps.php"));
  // the @When annotation, line 15 (1-based) = line 14 (0-based)
  const pos = new vscode.Position(14, 10);
  await waitFor("AC-2: usages of the @When definition", async () => {
    const res = await vscode.commands.executeCommand(
      "vscode.executeReferenceProvider",
      php.uri,
      pos
    );
    return toLocations(res).some(
      (l) => l.uri.fsPath.endsWith("commandes.feature") && l.range.start.line === 5
    );
  });
});

// --- AC-1/AC-2 completeness: the contract promises the FULL set --------------

test("AC-1/AC-2: completeness — the exact location set (no more, no less)", async () => {
  await waitForActivation();
  const commandes = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  // AC-1: the step at line 6 (1-based) resolves to EXACTLY one definition —
  // CommandeSteps.php line 15 (1-based) = 14 (0-based). The @Then of the
  // same method does not match ("est valide" ≠ "avec succès") and the
  // English/German definitions carry other patterns.
  const defs = toLocations(
    await vscode.commands.executeCommand(
      "vscode.executeDefinitionProvider",
      commandes.uri,
      new vscode.Position(5, 10)
    )
  );
  assert.equal(defs.length, 1, "AC-1: exactly one matching definition");
  assert.ok(
    defs[0].uri.fsPath.endsWith("CommandeSteps.php") &&
      defs[0].range.start.line === 14,
    `AC-1: the location is CommandeSteps.php line 14 (0-based): ${JSON.stringify(defs)}`
  );
  // AC-2: the @When definition (line 15 (1-based) = 14 (0-based)) resolves to
  // EXACTLY two steps — commandes.feature line 6 (5, 0-based) and
  // paiements.feature line 5 (4, 0-based).
  const php = await vscode.workspace.openTextDocument(docUri("CommandeSteps.php"));
  const refs = toLocations(
    await vscode.commands.executeCommand(
      "vscode.executeReferenceProvider",
      php.uri,
      new vscode.Position(14, 10)
    )
  )
    .map((l) => ({
      path: l.uri.fsPath.split(/[\\/]/).pop(),
      line: l.range.start.line,
    }))
    .sort((a, b) => (a.path + a.line).localeCompare(b.path + b.line));
  assert.deepEqual(
    refs,
    [
      { path: "commandes.feature", line: 5 },
      { path: "paiements.feature", line: 4 },
    ],
    "AC-2: exactly the two matching steps, no more, no less"
  );
});

test("AC-1/AC-2: Scenario Outline — each Examples row resolves (interpolated, per row)", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(docUri("orders_en.feature"));
  // Examples row | CMD-1 | — line 11 (1-based) = 10 (0-based). The Outline
  // step is interpolated per row (Behat runtime behavior): the row resolves
  // to exactly the @When definition (OrderSteps.php line 22 (1-based) =
  // 21 (0-based)) — the other two definitions match neither row.
  const defs = toLocations(
    await vscode.commands.executeCommand(
      "vscode.executeDefinitionProvider",
      doc.uri,
      new vscode.Position(10, 8)
    )
  );
  assert.equal(defs.length, 1, "exactly one matching definition for the row");
  assert.ok(
    defs[0].uri.fsPath.endsWith("OrderSteps.php") && defs[0].range.start.line === 21,
    `Outline row → OrderSteps.php line 21 (0-based): ${JSON.stringify(defs)}`
  );
  // Reverse: the @When definition resolves to exactly the two Examples rows
  // (10 and 11, 0-based) — not the placeholder line of the Outline step.
  const php = await vscode.workspace.openTextDocument(docUri("OrderSteps.php"));
  const refs = toLocations(
    await vscode.commands.executeCommand(
      "vscode.executeReferenceProvider",
      php.uri,
      new vscode.Position(21, 10)
    )
  )
    .map((l) => ({
      path: l.uri.fsPath.split(/[\\/]/).pop(),
      line: l.range.start.line,
    }))
    .sort((a, b) => (a.path + a.line).localeCompare(b.path + b.line));
  assert.deepEqual(
    refs,
    [
      { path: "orders_en.feature", line: 10 },
      { path: "orders_en.feature", line: 11 },
    ],
    "exactly the two Examples rows, no more, no less"
  );
});

test("AC-1: Background step resolves; the scenario step stays type-agnostic", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(docUri("e2e/background.feature"));
  // Background step — line 5 (1-based) = 4 (0-based): resolves to exactly
  // the @Given /I am/ definition (OrderSteps.php line 8 (1-based) = 7 (0-based)).
  const bgDefs = toLocations(
    await vscode.commands.executeCommand(
      "vscode.executeDefinitionProvider",
      doc.uri,
      new vscode.Position(4, 8)
    )
  );
  assert.equal(bgDefs.length, 1, "the background step resolves to exactly one definition");
  assert.ok(
    bgDefs[0].uri.fsPath.endsWith("OrderSteps.php") && bgDefs[0].range.start.line === 7,
    `background step → OrderSteps.php line 7 (0-based): ${JSON.stringify(bgDefs)}`
  );
  // Scenario step — line 8 (1-based) = 7 (0-based): a When step resolving to
  // a @Given definition — type-agnostic, as in the Behat runtime.
  const whenDefs = toLocations(
    await vscode.commands.executeCommand(
      "vscode.executeDefinitionProvider",
      doc.uri,
      new vscode.Position(7, 8)
    )
  );
  assert.equal(whenDefs.length, 1, "the scenario step resolves to exactly one definition");
  assert.ok(
    whenDefs[0].uri.fsPath.endsWith("OrderSteps.php") && whenDefs[0].range.start.line === 14,
    `scenario step → the @Given /I pay for/ definition, line 14 (0-based): ${JSON.stringify(whenDefs)}`
  );
  // Both steps resolve → no diagnostic on the file (no undefined step, and
  // no new orphan: the definitions keep their reference usages).
  assert.equal(
    vscode.languages.getDiagnostics(doc.uri).length,
    0,
    "no diagnostic on the background fixture"
  );
});

