test("AC-4: hover on an untranslatable definition → the reason (fail loud)", async () => {
  await waitForActivation();
  const doc = await vscode.workspace.openTextDocument(
    docUri("e2e/UntranslatableSteps.php")
  );
  const pos = new vscode.Position(7, 10); // annotation, line 8 (1-based)
  let text = "";
  // The fail-loud marker (normalized — the round trip escapes `*`), then
  // the reason in the untouched code block. NOT /\K|not supported/i: the
  // card carries the raw expression (with \K) in its own code block, so
  // that predicate would pass even without the marker or the reason.
  await waitFor("AC-4: untranslatable hover carries the fail-loud marker", async () => {
    const hovers = await vscode.commands.executeCommand(
      "vscode.executeHoverProvider",
      doc.uri,
      pos
    );
    text = hoverText(hovers);
    return text
      .replace(/&nbsp;/g, " ")
      .replace(/\\\*/g, "*")
      .includes("Untranslatable expression — never matched");
  });
  assert.ok(
    text.includes("PCRE escape \\K is not supported"),
    "the translation reason in the code block"
  );
});

