// --- AC-5: static rebuild (watcher → debounce → re-index) --------------------

test("AC-5: rebuild — a new feature file is indexed by the watcher", async () => {
  await waitForActivation();
  const file = join(workspaceRoot().fsPath, "rebuild_scratch.feature");
  await writeFile(
    file,
    "Feature: Rebuild\n\n  Scenario: Scratch\n    Given a step that exists nowhere\n",
    "utf8"
  );
  try {
    await waitFor(
      "AC-5: undefined-step diagnostic on the new file",
      async () => {
        const doc = await vscode.workspace.openTextDocument(vscode.Uri.file(file));
        return vscode.languages
          .getDiagnostics(doc.uri)
          .some((d) => d.severity === ERROR);
      },
      30000 // watcher + debounce + rebuild budget
    );
  } finally {
    await unlink(file).catch(() => {});
  }
});

// --- AC-3: vendor/ exclusion, positive proof ---------------------------------

test("AC-3: vendor/ exclusion — a vendored feature is never indexed", async () => {
  await waitForActivation();
  const root = workspaceRoot().fsPath;
  const vendorDir = join(root, "vendor");
  const vendorUri = vscode.Uri.file(join(vendorDir, "ignored.feature"));
  const scratch = join(root, "vendor_probe_scratch.feature");
  mkdirSync(vendorDir, { recursive: true });
  try {
    await writeFile(
      vendorUri.fsPath,
      "Feature: Vendored\n\n  Scenario: Probe\n    Given a step that exists nowhere\n",
      "utf8"
    );
    // A root-level scratch step forces the rebuild that runs while the
    // vendored file is on disk: its diagnostic is the proof the index
    // pipeline ran — the same publish would show the vendored diagnostic if
    // the exclusion failed.
    await writeFile(
      scratch,
      "Feature: Probe\n\n  Scenario: Scratch\n    Given a step that exists nowhere\n",
      "utf8"
    );
    const scratchDoc = await vscode.workspace.openTextDocument(vscode.Uri.file(scratch));
    await waitFor(
      "vendor probe: rebuild ran (scratch step diagnosed)",
      async () =>
        vscode.languages
          .getDiagnostics(scratchDoc.uri)
          .some((d) => d.severity === ERROR),
      30000 // watcher + debounce + rebuild budget
    );
    assert.equal(
      vscode.languages.getDiagnostics(vendorUri).length,
      0,
      "no diagnostic on the vendored feature — vendor/ is always excluded"
    );
    const commandes = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
    assert.ok(
      vscode.languages
        .getDiagnostics(commandes.uri)
        .some((d) => d.severity === ERROR),
      "the reference file is still diagnosed (positive control)"
    );
  } finally {
    await rm(scratch, { force: true });
    await rm(vendorDir, { recursive: true, force: true });
  }
});

// --- setting gates (run last: they mutate the workspace configuration) --------

test("AC-3: gherkinBehat.orphans=false → the orphan info is off (errors intact) → on", async () => {
  await waitForActivation();
  const php = await vscode.workspace.openTextDocument(docUri("CommandeSteps.php"));
  const commandes = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  const config = vscode.workspace.getConfiguration("gherkinBehat");
  try {
    await config.update("orphans", false, vscode.ConfigurationTarget.Workspace);
    await waitFor(
      "orphans off: the orphan info is gone while the error stays",
      async () => {
        const infos = vscode.languages.getDiagnostics(php.uri);
        const errors = vscode.languages.getDiagnostics(commandes.uri);
        return (
          !infos.some((d) => d.severity === INFO && /orphan/i.test(d.message)) &&
          errors.some((d) => d.severity === ERROR)
        );
      },
      30000
    );
  } finally {
    await config.update("orphans", true, vscode.ConfigurationTarget.Workspace);
  }
  await waitFor(
    "orphans on: the orphan info is back",
    async () =>
      vscode.languages
        .getDiagnostics(php.uri)
        .some((d) => d.severity === INFO && /orphan/i.test(d.message))
  );
});

test("AC-3: gherkinBehat.enabled=false → off switch (diagnostics cleared, providers empty) → on", async () => {
  await waitForActivation();
  const commandes = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  const php = await vscode.workspace.openTextDocument(docUri("CommandeSteps.php"));
  const config = vscode.workspace.getConfiguration("gherkinBehat");
  try {
    await config.update("enabled", false, vscode.ConfigurationTarget.Workspace);
    await waitFor(
      "enabled off: all diagnostics cleared",
      async () =>
        vscode.languages.getDiagnostics(commandes.uri).length === 0 &&
        vscode.languages.getDiagnostics(php.uri).length === 0,
      30000
    );
    // No index → the providers resolve to nothing (no file read, no match).
    assert.equal(
      toLocations(
        await vscode.commands.executeCommand(
          "vscode.executeDefinitionProvider",
          commandes.uri,
          new vscode.Position(5, 10)
        )
      ).length,
      0,
      "definition provider empty while off"
    );
    assert.equal(
      toLocations(
        await vscode.commands.executeCommand(
          "vscode.executeReferenceProvider",
          php.uri,
          new vscode.Position(14, 10)
        )
      ).length,
      0,
      "reference provider empty while off"
    );
  } finally {
    await config.update("enabled", true, vscode.ConfigurationTarget.Workspace);
  }
  await waitFor(
    "enabled on: the reference diagnostics are back",
    async () =>
      vscode.languages
        .getDiagnostics(commandes.uri)
        .some((d) => d.severity === ERROR),
    30000
  );
});

// --- CRASH-003: unreadable file → per-file diagnostic + partial index --------
// Run last (like the setting gates): mutates a workspace file's permission and
// the orphans setting, both restored in `finally`.

test("AC-3: unreadable feature file → error diagnostic + partial index (CRASH-003)", async () => {
  await waitForActivation();
  const brokenPath = join(workspaceRoot().fsPath, "e2e", "broken.feature");
  const brokenUri = docUri("e2e/broken.feature");
  const commandes = await vscode.workspace.openTextDocument(docUri("commandes.feature"));
  const config = vscode.workspace.getConfiguration("gherkinBehat");
  await chmod(brokenPath, 0o000);
  try {
    // Trigger the rebuild that runs while the file is unreadable: the
    // configuration change schedules it (the chmod's own file event may
    // coalesce into the same rebuild — either way, one build).
    await config.update("orphans", false, vscode.ConfigurationTarget.Workspace);
    await waitFor(
      "CRASH-003: read-failure diagnostic on the unreadable file",
      async () =>
        vscode.languages
          .getDiagnostics(brokenUri)
          .some((d) => d.severity === ERROR && /cannot read file/i.test(d.message)),
      30000 // watcher + debounce + rebuild budget
    );
    // The file cannot be parsed while unreadable: exactly one diagnostic on
    // it — the read failure (the old parse-error is replaced, nothing is lost
    // silently, nothing else is fabricated).
    const brokenDiag = vscode.languages.getDiagnostics(brokenUri);
    assert.equal(
      brokenDiag.length,
      1,
      `one diagnostic on the unreadable file: ${JSON.stringify(
        brokenDiag.map((d) => d.message)
      )}`
    );
    // Partial index: the rest of the workspace is still indexed — the
    // reference undefined step keeps its diagnostic...
    assert.ok(
      vscode.languages
        .getDiagnostics(commandes.uri)
        .some((d) => d.severity === ERROR),
      "the reference file is still diagnosed (partial index)"
    );
    // ...and navigation still resolves through the partial index.
    const defs = toLocations(
      await vscode.commands.executeCommand(
        "vscode.executeDefinitionProvider",
        commandes.uri,
        new vscode.Position(5, 10)
      )
    );
    assert.ok(
      defs.some(
        (l) =>
          l.uri.fsPath.endsWith("CommandeSteps.php") && l.range.start.line === 14
      ),
      "navigation still resolves through the partial index"
    );
  } finally {
    await chmod(brokenPath, 0o644).catch(() => {});
    await config.update("orphans", true, vscode.ConfigurationTarget.Workspace);
  }
  await waitFor(
    "CRASH-003: after restore, the parse-error diagnostic is back",
    async () =>
      vscode.languages
        .getDiagnostics(brokenUri)
        .some((d) => d.severity === ERROR && /unparseable/i.test(d.message)),
    30000
  );
});

// --- entry point (called by the extension host) ------------------------------

/**
 * @param {string} testsPath — this module's file path (passed by the host).
 * @param {(error?: Error, failures?: number) => void} [_onComplete] —
 *   optional host callback; unused (Promise channel only).
 */
export function run(testsPath, _onComplete) {
  void _onComplete;
  void testsPath;
  return (async () => {
    let failures = 0;
    for (const { name, fn } of tests) {
      try {
        await fn();
        console.log(`ok - ${name}`);
      } catch (err) {
        failures += 1;
        console.error(`FAIL - ${name}`);
        console.error(err);
      }
    }
    console.log(`E2E suite: ${tests.length - failures}/${tests.length} passed`);
    if (failures > 0) {
      throw new Error(`${failures}/${tests.length} e2e test(s) failed`);
    }
  })();
}
